// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;
pragma experimental ABIEncoderV2;

import {Test} from "forge-std/Test.sol";
import "../src/Jesus.sol";

contract JesusTradingTest is Test {
    Jesus public token;
    address public owner;
    address public alice;
    address public bob;

    // Mock addresses
    address constant routerAddress = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;
    address mockFactory = address(0x123);
    address mockWETH = address(0x456);
    address mockPair = address(0x789);

    function setUp() public {
        // Setup accounts
        owner = makeAddr("owner");
        alice = makeAddr("alice");
        bob = makeAddr("bob");

        // Initialize router address with empty contract code
        vm.etch(routerAddress, hex"00");

        // Mock router calls
        vm.mockCall(
            routerAddress,
            abi.encodeWithSignature("factory()"),
            abi.encode(mockFactory)
        );
        vm.mockCall(
            routerAddress,
            abi.encodeWithSignature("WETH()"),
            abi.encode(mockWETH)
        );

        // Mock factory createPair call
        vm.mockCall(
            mockFactory,
            abi.encodeWithSignature("createPair(address,address)"),
            abi.encode(mockPair)
        );

        // Deploy token as owner
        vm.prank(owner);
        token = new Jesus();

        // Transfer tokens to alice
        vm.prank(owner);
        token.transfer(alice, 1000 * 1e18);
    }

    function testTransferWhenTradingDisabled() public {
        // Alice attempts transfer - should fail (non-excluded)
        vm.prank(alice);
        vm.expectRevert("Trading is not active.");
        token.transfer(bob, 100 * 1e18);
    }

    function testEnableTrading() public {
        // Owner enables trading
        vm.prank(owner);
        token.enableTrading();

        // Verify transfer succeeds after enabling
        vm.prank(alice);
        token.transfer(bob, 100 * 1e18);
        assertEq(token.balanceOf(bob), 100 * 1e18);

        // Verify trading cannot be disabled after enabling
        // (Function to disable doesn't exist, but test continues to function)
        vm.prank(alice);
        token.transfer(bob, 100 * 1e18);
        assertEq(token.balanceOf(bob), 200 * 1e18);
    }
}
```
