        uint256 preTriggerAliceBalance = token.balanceOf(alice);
        uint256 preTriggerBobBalance = token.balanceOf(bob);

        console.log("Trading active state:", preTriggerTradingActive);
        console.log("Alice balance:", preTriggerAliceBalance);
        console.log("Bob balance:", preTriggerBobBalance);

