        } else {
            console.log("Vulnerability not Exist: Trading state remains consistent after operations");
        }

        // Original continuance below - preserves existing test logic
        assertEq(token.balanceOf(bob), 100 * 1e18, "Initial transfer failed");

        // Verify trading cannot be disabled after enabling
        vm.prank(alice);
        token.transfer(bob, 100 * 1e18);
        assertEq(token.balanceOf(bob), 200 * 1e18, "Secondary transfer failed");
    }
}
